() => {
  const body = getComputedStyle(document.body);
  const html = document.documentElement;
  return {
    htmlClass: html.className,
    htmlDataTheme: html.getAttribute('data-theme'),
    bodyBg: body.backgroundColor,
    bodyColor: body.color
  };
}

