() => {
  const results = [];
  const ta = document.querySelector('textarea, input[type="text"]');
  if (ta) {
    const cs = getComputedStyle(ta);
    results.push({el: 'input', color: cs.color, bg: cs.backgroundColor, placeholderColor: getComputedStyle(ta, '::placeholder').color});
  }
  // Sample text nodes and check contrast issues: light color on light bg
  const walker = document.createTreeWalker(document.querySelector('main'), NodeFilter.SHOW_ELEMENT);
  let bad = [];
  let node;
  while ((node = walker.nextNode())) {
    if (node.children.length === 0 && node.textContent.trim()) {
      const cs = getComputedStyle(node);
      const c = cs.color;
      const m = c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
      if (m) {
        const lum = (0.2126*+m[1] + 0.7152*+m[2] + 0.0722*+m[3]) / 255;
        const alpha = m[4] !== undefined ? parseFloat(m[4]) : 1;
        // light text (lum > 0.85) possibly invisible on white
        if (lum > 0.9 && alpha > 0.5) {
          // find effective bg by walking up
          let p = node, bg = null;
          while (p && p !== document.body) {
            const pcs = getComputedStyle(p);
            if (pcs.backgroundColor && pcs.backgroundColor !== 'rgba(0, 0, 0, 0)') { bg = pcs.backgroundColor; break; }
            p = p.parentElement;
          }
          bad.push({text: node.textContent.trim().slice(0, 20), color: c, bg: bg});
        }
      }
    }
  }
  return { inputs: results, suspiciousLightTextCount: bad.length, samples: bad.slice(0, 10) };
}

() => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.trim() === '智能查询');
  return btns.map(b => {
    const cs = getComputedStyle(b);
    return { disabled: b.disabled, color: cs.color, bg: cs.backgroundColor, bgImage: cs.backgroundImage, border: cs.borderColor, opacity: cs.opacity };
  });
}

